import type { LessonScreen } from "./types";

/**
 * Batch 5: the last 20 DJ lessons (crossfader-technique to dj-advanced-complete).
 * No em dashes. Checked against rekordbox support pages: stems are 3 or 4 (VOCAL, INST, DRUMS, plus BASS in 4-stem mode);
 * key lock is labelled Master Tempo on Pioneer CDJs and MT in rekordbox; Sound Color FX is a per-channel knob, off at 12 o'clock.
 * Gear-specific limits (key shift range, which effects a unit has) are taught as ideas, with "check your unit".
 */
export const FLAGSHIP_BATCH_5: Record<string, LessonScreen[]> = {
  "crossfader-technique": [
    { kind: "hook", emoji: "", headline: "One slider, two very different jobs", subtext: "Hip-hop DJs live on it. Many house DJs barely touch it." },
    { kind: "concept", title: "What it does", body: "The crossfader moves the blend between the left and right channels. All the way left is only the left channel, all the way right only the right, the middle both. A slow move is a blend. A fast move on the beat is a cut.", keyFact: "Slow move blends. Fast move cuts.", visual: "mixer-channel" },
    { kind: "interact", sim: "mixer", prompt: "Blend slowly, then cut on a beat." },
    { kind: "concept", title: "Curves", body: "Most mixers let you change the crossfader curve. A sharp curve opens the sound almost at once, which suits cutting and scratching. A smooth curve brings the second channel in gradually, which suits blending. Many mixers also let you reverse the fader's direction.", keyFact: "Sharp curve for cuts. Smooth curve for blends." },
    { kind: "quiz", q: "You are cutting between two hip-hop tracks on the beat and the first track keeps leaking in as you move the fader. What do you adjust?", options: ["Set the crossfader curve to sharp", "Raise the gain", "Cut the bass on both", "Slow the tempo"], answer: 0, explain: "A sharp curve cuts the other channel almost immediately, so there is no leak as you move. A smooth curve keeps both audible across much of the throw.", hint: "Which curve opens fast?" },
    { kind: "quiz", q: "You are mixing a long house blend. Why do many DJs use the channel faders and EQ instead of the crossfader?", options: ["They get finer control over level and bass for each track separately", "The crossfader is broken", "Channel faders are louder", "The crossfader changes the tempo"], answer: 0, explain: "A crossfader moves both channels at once. Channel faders and EQ let you treat each track on its own, which a long blend needs.", hint: "Think about two separate bass lines." },
    { kind: "match", prompt: "Match the position to what you hear", pairs: [{ left: "Fully left", right: "Only the left channel" }, { left: "Fully right", right: "Only the right channel" }, { left: "Centre", right: "Both channels together" }, { left: "Fast move on a beat", right: "A cut" }] },
    { kind: "concept", title: "Pick the tool for the style", body: "Neither approach is more correct. Cuts and scratches are the heart of hip-hop and turntablism. Long EQ blends are the habit of house and techno. A good DJ knows both and chooses for the music.", keyFact: "Style decides the tool." },
    { kind: "quiz", q: "From an earlier lesson: what does a bass swap prevent?", options: ["Two bass lines playing at full volume at once", "Tempo drift", "Key clash", "A dead USB"], answer: 0, explain: "Swapping the bass keeps only one low end playing, so the mix stays clean." },
    { kind: "summary", learned: ["Crossfader position sets the blend, speed sets blend or cut", "Sharp curve for cuts, smooth for blends", "House DJs often use channel faders and EQ instead"] },
  ],

  "long-mix-blend": [
    { kind: "hook", emoji: "", headline: "The crowd should not notice the swap", subtext: "A long blend moves the room from one track to the next without a seam." },
    { kind: "concept", title: "The shape of a long blend", body: "Start the incoming track with its bass turned down. Raise its fader slowly over 16 to 32 bars. Around the midpoint do the bass swap, then bring the outgoing track down. Both tracks share the room for a while, so they must stay in time and not fight.", keyFact: "Fade in, swap the bass, fade out." },
    { kind: "interact", sim: "mixer", prompt: "Run a long blend. Swap the bass midway." },
    { kind: "sequence", prompt: "Put the long blend in order", items: ["Start the incoming track, bass cut", "Raise the incoming fader slowly", "Swap the bass between the two", "Lower the outgoing fader", "Remove the outgoing track"], explain: "Bass is kept off the incoming track until the swap so the low end never doubles. The outgoing track leaves last." },
    { kind: "concept", title: "Use the tracks' own space", body: "Many dance tracks have long, sparse intros and outros built for mixing. On the waveform they look thin. Blend in those zones and the busy parts of each track never collide.", keyFact: "Blend where both tracks are sparse." },
    { kind: "quiz", q: "You start a blend while the outgoing track is in its busiest section and the incoming one has a loud intro. It sounds crowded. What is the fix?", options: ["Start the blend when the outgoing track reaches a sparser section", "Turn both up", "Add reverb to both", "Speed up the tempo"], answer: 0, explain: "Two busy sections add up and clash. Wait for a breakdown or outro so one of the tracks is giving space.", hint: "Find the thin parts." },
    { kind: "quiz", q: "The kicks stay locked but vocals from both tracks clash during the blend. What do you try?", options: ["Cut the mids on one of the tracks", "Raise the master", "Reverse the crossfader", "Boost both bass bands"], answer: 0, explain: "Vocals live in the mids. Cutting mids on one track clears room for the other.", hint: "Where do vocals sit?" },
    { kind: "concept", title: "Phrase boundaries", body: "Dance tracks are built in phrases, often 8, 16 or 32 bars. Start your blend at the start of a phrase so the changes in both tracks line up and the join feels planned.", keyFact: "Start on the phrase, not mid-phrase." },
    { kind: "quiz", q: "From an earlier lesson: the pitch fader sets what?", options: ["The tempo of the deck", "The phase of the beats", "The channel gain", "The key only"], answer: 0, explain: "The pitch control sets speed. The jog wheel nudges the position, which is the phase." },
    { kind: "summary", learned: ["Blend over 16 to 32 bars with a bass swap in the middle", "Blend in sparse sections and start on a phrase", "Cut mids to separate clashing vocals"] },
  ],

  "transitions-cut-dj": [
    { kind: "hook", emoji: "", headline: "A cut is only a mistake if you hesitate", subtext: "Done on purpose, on the beat, it is one of the strongest moves you have." },
    { kind: "concept", title: "The cut", body: "A cut jumps from one track to the next with no overlap, ideally on the first beat of a new phrase. It works when both tracks are in time, the new one starts right on the downbeat, and the move is confident.", keyFact: "Cut on the downbeat of a phrase." },
    { kind: "interact", sim: "mixer", prompt: "Cut to the next track on the downbeat." },
    { kind: "quiz", q: "You cut to the next track but it lands a half beat late and sounds like a stumble. What went wrong?", options: ["The cue point or timing was off the downbeat", "The crossfader curve is smooth", "The headphones were muted", "The key was wrong"], answer: 0, explain: "A cut has no overlap to hide a mistake, so the start must land on the beat. Set a cue on the first beat and trigger it exactly on the bar.", hint: "Where did the new track start?" },
    { kind: "concept", title: "Echo out", body: "Add a beat-synced echo to the last beat or bar of the outgoing track, then cut the dry signal. The echo tail carries on after the track has gone and bridges into the next one.", keyFact: "Echo out lets the tail cover the join." },
    { kind: "concept", title: "Reverb wash", body: "Send the outgoing track into a lot of reverb and cut the dry signal. The wash fills the gap while the new track starts. Use it sparingly or the join sounds smeared.", keyFact: "Wash fills the gap. Use sparingly." },
    { kind: "quiz", q: "You finish a high-energy track and want a clean break before a slower one. Which move fits best?", options: ["Echo out, then start the new track on the next phrase", "Long bass swap blend", "Raise the master", "Loop the last beat forever"], answer: 0, explain: "The echo tail bridges the silence, and starting on a phrase keeps the next track in time.", hint: "Clean break, not a blend." },
    { kind: "match", prompt: "Match the move to its effect", pairs: [{ left: "Cut", right: "Instant jump on the beat" }, { left: "Echo out", right: "Tail carries past the cut" }, { left: "Reverb wash", right: "Fills the gap with a haze" }, { left: "Bass swap blend", right: "Gradual handover with no gap" }] },
    { kind: "quiz", q: "From an earlier lesson: what is the first thing to check if sync sounds off beat?", options: ["The beat grid", "The speakers", "The key", "The gain"], answer: 0, explain: "Sync follows the grid, so a wrong grid sends the track off the beat." },
    { kind: "summary", learned: ["Cut on the downbeat of a phrase, with confidence", "Echo out and reverb wash cover the join", "No overlap means no room for timing mistakes"] },
  ],

  "loop-function-dj": [
    { kind: "hook", emoji: "", headline: "Hold a moment for as long as you need", subtext: "A loop buys you time and builds tension." },
    { kind: "concept", title: "What a loop does", body: "A loop repeats a chosen section of a track until you release it. You set a start and end, often by length in beats or bars, and halve or double the length while it plays. A four-bar loop on a breakdown gives you time to line up the next track.", keyFact: "Loop to buy time." },
    { kind: "interact", sim: "loop-roll", prompt: "Set a loop. Halve it. Release it." },
    { kind: "concept", title: "Loop roll", body: "A loop roll repeats a very short slice while you hold the control. When you let go, the track continues from where it would have been, as if it had kept playing underneath. It is a stutter effect, not a way to hold a moment.", keyFact: "Roll stutters, then snaps back." },
    { kind: "quiz", q: "You want to repeat the last bar of a breakdown for eight bars while you line up the next track. Which control?", options: ["A normal loop", "A loop roll", "The crossfader", "Reverb"], answer: 0, explain: "A normal loop keeps repeating until you release it. A roll snaps back to the original position when you let go.", hint: "Hold, not stutter." },
    { kind: "quiz", q: "You hold a loop roll on the snare of a drop and let go. Where is the track now?", options: ["Where it would be had it kept playing", "At the start of the track", "At the start of the loop", "Paused"], answer: 0, explain: "A roll runs the track silently underneath, so on release you rejoin the original timeline.", hint: "It never stopped." },
    { kind: "match", prompt: "Match the control to its result", pairs: [{ left: "Loop", right: "Repeats until released" }, { left: "Loop roll", right: "Repeats while held, then rejoins" }, { left: "Halve", right: "Makes the loop shorter" }, { left: "Double", right: "Makes the loop longer" }] },
    { kind: "concept", title: "Loops and the grid", body: "Loops snap to the beat grid, so a wrong grid gives a loop that sounds off the beat. Check the grid before you rely on loops.", keyFact: "Grid first, loops second." },
    { kind: "quiz", q: "From an earlier lesson: what is a cue point for?", options: ["A saved position to jump to", "A volume setting", "A key label", "A BPM correction"], answer: 0, explain: "Cue points are bookmarks inside a track." },
    { kind: "summary", learned: ["A loop repeats until released, a roll rejoins the track", "Halve and double change the loop length", "Loops depend on a correct beat grid"] },
  ],

  "reading-the-crowd": [
    { kind: "hook", emoji: "", headline: "The floor answers every question you ask", subtext: "Reading the room beats any technical trick." },
    { kind: "concept", title: "What to watch", body: "Look at where people are standing and facing. Dancing, turning to the DJ and singing along are good signs. Turning to the bar, checking phones and drifting off the floor are signs the music is not landing. Watch for trends, not single people.", keyFact: "Watch the floor, not one person." },
    { kind: "interact", sim: "song-structure", prompt: "Map a night. Where does energy sit?" },
    { kind: "concept", title: "Time of night", body: "Early in the night people arrive, chat and warm up, so lower energy fits. Mid-night the floor is full and ready for the strongest music. Late in the night people may be winding down or getting a second wind. The same track can work at one hour and flop at another.", keyFact: "The same track fits one hour and not another." },
    { kind: "quiz", q: "It is early, the room is half full, and you drop your biggest track. People stop dancing. What happened?", options: ["The track suited the peak, not the warm-up", "The track was bad", "The speakers broke", "The BPM was wrong"], answer: 0, explain: "Energy has to match the room's state. A peak track too early burns your best material and can empty the floor.", hint: "Timing, not quality." },
    { kind: "quiz", q: "A group asks for a song that does not fit your set. What is a sensible approach?", options: ["Treat it as information, then decide whether it serves the room", "Always play it", "Ignore all requests rudely", "Stop the music"], answer: 0, explain: "Requests tell you what some of the room wants. You can play, adapt or politely pass, but you stay in charge of the set.", hint: "Information, not orders." },
    { kind: "quiz", q: "You see people leaving the floor during a long breakdown. What is a good move?", options: ["Bring in the drop or switch to something more driving", "Extend the breakdown", "Quieten the master", "Play a slower track"], answer: 0, explain: "A long wait with no payoff loses people. Shortening the build or moving on keeps them with you.", hint: "Give them something." },
    { kind: "concept", title: "Adjust fast, adjust small", body: "You rarely need a big change. Nudge the tempo, change the style a little, or bring a vocal in. Small adjustments keep the flow, big ones jolt it.", keyFact: "Small nudges beat big swerves." },
    { kind: "quiz", q: "From an earlier lesson: what is the core skill of a DJ?", options: ["The order of tracks and the joins between them", "Owning the most gear", "Scratching", "Having the largest library"], answer: 0, explain: "The decisions about order and transitions shape how the room feels." },
    { kind: "summary", learned: ["Watch trends on the floor, not single people", "Match energy to the time of night", "Treat requests as information"] },
  ],

  "set-structure-dj": [
    { kind: "hook", emoji: "", headline: "A set has a shape", subtext: "Plan the arc and the night feels like a story." },
    { kind: "concept", title: "The arc", body: "Most sets move through four stages. Warm-up starts low and welcomes people in. The build raises energy step by step. The peak holds the strongest music. The wind-down brings the room down gently. Peaks mean more when there are valleys before them.", keyFact: "Warm up, build, peak, wind down." },
    { kind: "interact", sim: "arrangement", prompt: "Draw an energy arc for a two-hour set." },
    { kind: "sequence", prompt: "Put the stages of a set in order", items: ["Warm-up", "Build", "Peak", "Wind-down"], explain: "Energy rises through the first stages to the peak and then eases off, so the room is brought down rather than dropped." },
    { kind: "concept", title: "Know your slot", body: "A warm-up slot is not a headline slot. If you open, your job is to bring people in, not to play the biggest records. If you close, you carry the room out. Plan the stages for your slot length.", keyFact: "Your slot sets your job." },
    { kind: "quiz", q: "You are playing a 2 hour warm-up and you start with your biggest tracks. What is the risk?", options: ["There is nowhere left to go and the headliner follows an exhausted room", "None", "The sound is too quiet", "Nobody will notice"], answer: 0, explain: "A warm-up that peaks early uses the room's energy before the headliner. Build slowly and leave room for the next set.", hint: "Think about who plays after you." },
    { kind: "quiz", q: "You have a 2 hour set. Which split is a sensible starting plan?", options: ["Time for a warm-up, a build, a peak and a short wind-down", "Peak for the whole two hours", "Wind-down first", "Random order"], answer: 0, explain: "Planning rough time for each stage keeps the arc intact. You can adjust, but a plan stops you peaking too soon.", hint: "Every stage has a share." },
    { kind: "match", prompt: "Match the stage to its job", pairs: [{ left: "Warm-up", right: "Welcome the early crowd" }, { left: "Build", right: "Raise energy step by step" }, { left: "Peak", right: "Play the strongest music" }, { left: "Wind-down", right: "Ease the room down" }] },
    { kind: "quiz", q: "From an earlier lesson: why plan a focused gig playlist?", options: ["Fewer options make faster, better choices", "It changes the key", "It makes tracks louder", "It is required by law"], answer: 0, explain: "A prepared set of tracks lets you spend your attention on the room." },
    { kind: "summary", learned: ["A set moves through warm-up, build, peak and wind-down", "Your slot decides your job", "Peaking too early leaves nowhere to go"] },
  ],

  "harmonic-mixing-dj": [
    { kind: "hook", emoji: "", headline: "Make blends that sound like one piece of music", subtext: "Keys that fit let the melodies share space." },
    { kind: "concept", title: "Using the key", body: "Look at each track's key before you blend. Same key, the relative major or minor (same number, other letter on the Camelot wheel), or a neighbour one step along are the safest choices for long overlaps. These are guides: your ear has the last word.", keyFact: "Same, relative, or one step along.", visual: "chord-stack" },
    { kind: "interact", sim: "harmonic-mix-wheel", prompt: "Pick the next key. Keep it compatible." },
    { kind: "concept", title: "Moving up the wheel", body: "One step up the wheel (for example 8A to 9A) moves a fifth up. Many DJs use that move to lift the energy, and one step down to ease it. That is a common habit, not a law.", keyFact: "Up lifts. Down eases. Common habit." },
    { kind: "quiz", q: "Your current track is 8A. Which choice is most likely to blend smoothly over a long overlap?", options: ["8B or 9A", "3B", "12A", "5A"], answer: 0, explain: "8B is the relative major and 9A is a neighbour, so they share most of their notes with 8A.", hint: "Close on the wheel." },
    { kind: "quiz", q: "Two tracks have keys that clash, but you love both. What can you do?", options: ["Keep the overlap short, or cut the melodic parts of one with EQ", "Overlap them for 32 bars", "Raise the gain on both", "Play them together at full volume"], answer: 0, explain: "A short overlap, or removing the melodic content from one track, avoids the clash.", hint: "Reduce the time they share notes." },
    { kind: "concept", title: "Key lock and key shift", body: "Key lock, called Master Tempo on Pioneer CDJs and MT in rekordbox, keeps a track's key steady while you change its tempo. Some players and software also let you shift the key by semitones. Larger shifts tend to sound more processed, so use small ones and listen.", keyFact: "Key lock holds the key. Small shifts sound best." },
    { kind: "quiz", q: "From an earlier lesson: why can a track's key analysis be wrong?", options: ["Analysis is an estimate, and drum-only parts have no key", "Keys never change", "The file is too short", "The headphones are muted"], answer: 0, explain: "Key analysis can miss, so trust your ear as the final check." },
    { kind: "summary", learned: ["Same key, relative key or one step along blends best", "One step up often lifts energy", "Key lock holds the key, small shifts sound best"] },
  ],

  "effects-performance-dj": [
    { kind: "hook", emoji: "", headline: "An effect should have a reason", subtext: "One good effect at the right moment beats ten bad ones." },
    { kind: "concept", title: "Two kinds of effects", body: "Many Pioneer DJ mixers have beat effects, which sync to the track's tempo, such as echo and reverb. They also have a Sound Color FX knob on each channel, which is a quick effect like a filter. On many units the knob is off at the 12 o'clock position and you turn left or right to add the effect.", keyFact: "Beat FX follow tempo. Sound Color FX is a per-channel knob." },
    { kind: "interact", sim: "mixer", prompt: "Sweep a filter into the drop." },
    { kind: "concept", title: "The filter sweep", body: "A low-pass filter removes high frequencies as you close it, so the track sounds like it is moving behind a wall. Closing it before a drop builds tension, and opening it again releases it.", keyFact: "Close to build, open to release." },
    { kind: "quiz", q: "You close the filter slowly over eight bars into a drop. What does the crowd feel?", options: ["Tension that releases when the drop hits", "Nothing", "A change of key", "A slower tempo"], answer: 0, explain: "Taking away the highs builds anticipation, and the full sound returning at the drop feels like release.", hint: "Think about what you removed." },
    { kind: "quiz", q: "You use echo, reverb and a flanger at once on every transition for an hour. What is the likely result?", options: ["The effects stop meaning anything and the music gets buried", "The crowd loves it", "The tempo changes", "The key changes"], answer: 0, explain: "Effects work because they are unusual. Used constantly they become noise and hide the music.", hint: "Restraint." },
    { kind: "match", prompt: "Match the effect to its use", pairs: [{ left: "Echo", right: "Tail that carries into the next track" }, { left: "Reverb", right: "Wash that blurs a join" }, { left: "Filter", right: "Builds tension before a drop" }, { left: "Sound Color FX knob", right: "Quick per-channel effect" }] },
    { kind: "concept", title: "Check your unit", body: "Each mixer has its own list of effects and its own controls. Read the manual for yours and find the three effects you will use most.", keyFact: "Learn three effects well." },
    { kind: "quiz", q: "From an earlier lesson: what does an echo out do?", options: ["Lets the tail carry past the cut", "Raises the BPM", "Swaps the bass", "Changes the key"], answer: 0, explain: "The echo tail bridges the gap between the outgoing and incoming tracks." },
    { kind: "summary", learned: ["Beat FX follow tempo, Sound Color FX is a per-channel knob", "A filter sweep builds tension and releases it", "Use a few effects with a reason"] },
  ],

  "energy-management-dj": [
    { kind: "hook", emoji: "", headline: "Contrast makes peaks feel higher", subtext: "A room that never rests never peaks." },
    { kind: "concept", title: "Tools for energy", body: "You control energy with tempo, how dense or sparse the tracks are, the intensity of the style, effects and how you mix. Build by raising several of these step by step. Release by dropping to something sparser, like a breakdown or a slower track.", keyFact: "Build, hold, release, repeat." },
    { kind: "interact", sim: "arrangement", prompt: "Draw a build, a peak and a valley." },
    { kind: "quiz", q: "You have played peak-energy tracks for 45 minutes and the floor looks tired. What can help?", options: ["A short, planned release such as a sparse or slower track, then build again", "More of the same", "Louder master", "A slower and slower set"], answer: 0, explain: "A valley lets people recover so the next build lands harder. Constant peak numbs a room.", hint: "Give them a breath." },
    { kind: "concept", title: "The double drop", body: "A double drop brings the drops of two tracks in at the same moment. It needs matching tempo, aligned phrases and compatible keys and basses. It can be huge, and it can also be a mess, so rehearse it.", keyFact: "Rehearse it. Double drops are hard." },
    { kind: "quiz", q: "You try a double drop but the two bass lines clash and the drop sounds muddy. What would have helped?", options: ["Cut the bass on one track and align the phrases", "Add more bass", "Speed up one track", "Change the master"], answer: 0, explain: "Two drops at once still need one bass line at a time, so cut the low end of one and keep both phrases aligned.", hint: "One low end only." },
    { kind: "match", prompt: "Match the tool to what it changes", pairs: [{ left: "Tempo", right: "How fast the room feels" }, { left: "Density", right: "How busy the sound is" }, { left: "Breakdown", right: "A release of tension" }, { left: "Filter sweep", right: "Builds anticipation" }] },
    { kind: "concept", title: "Plan the dips", body: "Mark where you intend to ease off, not only where you intend to peak. A set with no valleys is harder to build and harder to dance to.", keyFact: "Plan the valleys too." },
    { kind: "quiz", q: "From an earlier lesson: what are the four stages of a set?", options: ["Warm-up, build, peak, wind-down", "Peak, peak, peak, peak", "Wind-down, build, peak, warm-up", "Peak, warm-up, build, wind-down"], answer: 0, explain: "The arc runs low, up, high, down." },
    { kind: "summary", learned: ["Control energy with tempo, density, effects and style", "Release makes the next build land harder", "Rehearse a double drop before you use it live"] },
  ],

  "genre-strategy-dj": [
    { kind: "hook", emoji: "", headline: "People should know what you do", subtext: "A clear sound is easier to book and easier to remember." },
    { kind: "concept", title: "Define your sound", body: "A DJ's sound is the mix of styles, tempo range, mood and the kind of room they play. When promoters know what you do, they know when to book you. A clear identity is not a cage: it is a starting point.", keyFact: "A clear sound makes you easy to book." },
    { kind: "interact", sim: "bpm-tap", prompt: "Tap your favourite track. Find your home tempo." },
    { kind: "concept", title: "Widen one step at a time", body: "Move into styles that sit next to yours, such as deep house into tech house. Adjacent styles share tempo and feel, so the mix stays coherent and your audience can follow you.", keyFact: "Adjacent styles, one step at a time." },
    { kind: "quiz", q: "You play warm deep house and suddenly book a hard techno night. What is the likely problem?", options: ["The jump is too big, so your usual tracks and tempo may not fit", "None", "The speakers", "The key"], answer: 0, explain: "Moving across styles needs new tracks, new tempo ranges and new habits. A step to a neighbouring style is easier to do well.", hint: "How far apart are they?" },
    { kind: "quiz", q: "Why play music you actually love?", options: ["Enthusiasm shows in how you select and play", "Nobody notices", "It is cheaper", "It guarantees bookings"], answer: 0, explain: "Passion shows in choices and delivery. It also keeps you motivated through years of preparation.", hint: "What does the room feel?" },
    { kind: "match", prompt: "Match the genre to a typical neighbour", pairs: [{ left: "Deep house", right: "Tech house" }, { left: "Tech house", right: "Techno" }, { left: "Techno", right: "Hard techno" }, { left: "UK garage", right: "Breaks" }] },
    { kind: "concept", title: "Let it evolve", body: "Your sound will change as your taste and your audience change. Notice what you keep returning to and let it grow, rather than trying to fit a label.", keyFact: "Identity grows with you." },
    { kind: "quiz", q: "From an earlier lesson: why can half-time and double-time tracks be mixed together?", options: ["They share the same beat grid", "They share a key", "They have the same drums", "They never clash"], answer: 0, explain: "Double the tempo lines up beat for beat with the slower track." },
    { kind: "summary", learned: ["A clear sound makes you recognisable and bookable", "Widen into adjacent styles one step at a time", "Play what you genuinely love"] },
  ],

  "preparing-a-set-dj": [
    { kind: "hook", emoji: "", headline: "Preparation is half the performance", subtext: "A clear plan frees you to react to the room." },
    { kind: "concept", title: "Know the gig", body: "Find out who the crowd is, when you play, how long you have, what plays before and after, and what the venue wants. Then choose 60 to 100 tracks for that night rather than carrying the whole library.", keyFact: "Prepare for this gig, not every gig." },
    { kind: "interact", sim: "arrangement", prompt: "Lay out your first three tracks." },
    { kind: "concept", title: "Your first three tracks", body: "The opening tracks set the tone. Choose them on purpose, know how they mix into each other and have a backup in case the room does not fit. After that you adapt.", keyFact: "Open with a decision, then adapt." },
    { kind: "quiz", q: "You arrive and find the previous DJ played very high energy. Your planned opener is quiet. What do you do?", options: ["Pick a backup opener that fits the room and ease the energy", "Play your quiet opener anyway", "Leave", "Stop the music"], answer: 0, explain: "A prepared backup lets you adapt without panic. The plan serves the room, not the other way round.", hint: "Plan B." },
    { kind: "sequence", prompt: "Put gig preparation in order", items: ["Find out about the gig", "Choose 60 to 100 tracks", "Check grids and cues", "Export to two USBs", "Test on a player at the venue"], explain: "Understand the gig, choose, then prepare and export. Test on real gear last so any problem shows up before you play." },
    { kind: "quiz", q: "You export your USB on arrival and find a cue point missing. What would have avoided this?", options: ["Export and test the USB at home before the gig", "Bring a bigger USB", "Skip cue points", "Arrive earlier"], answer: 0, explain: "A tested export shows problems when you can still fix them.", hint: "Test early." },
    { kind: "concept", title: "Arrive early", body: "Arrive early enough to check the booth, test your USB and gain levels, and meet the sound engineer. Ten minutes of checking beats ten minutes of panic.", keyFact: "Arrive early. Check the booth." },
    { kind: "quiz", q: "From an earlier lesson: why bring two identical USBs?", options: ["One can fail or fail to read", "They make the music louder", "They hold more tracks", "They change the key"], answer: 0, explain: "A spare is your insurance against a failed drive." },
    { kind: "summary", learned: ["Know the gig and choose 60 to 100 tracks", "Plan your opening and a backup", "Test your USB at home and arrive early"] },
  ],

  "live-mistakes-dj": [
    { kind: "hook", emoji: "", headline: "Everyone makes mistakes. Recovery is the skill.", subtext: "A calm fix often goes unnoticed." },
    { kind: "concept", title: "The train wreck", body: "A train wreck is two tracks playing out of time with each other. The usual fix is simple: take the incoming track out of the speakers, keep the main track playing, and sort the incoming one out in your headphones.", keyFact: "Take one out. Fix it in the headphones." },
    { kind: "interact", sim: "beatmatch-trainer", prompt: "Recover from an off-beat blend." },
    { kind: "sequence", prompt: "Put the recovery in order", items: ["Notice the clash", "Take the incoming track out of the speakers", "Cue it in the headphones", "Re-match the tempo and phase", "Bring it back in"], explain: "Remove the clash first, then repair in private, then bring it back in only once it locks." },
    { kind: "quiz", q: "The two kicks are clearly drifting apart and the crowd is turning. What is the fastest clean fix?", options: ["Pull the incoming fader down and re-match in your headphones", "Turn both up", "Add a reverb wash", "Stop the music"], answer: 0, explain: "Silence the clash, keep the music going with the main track, and fix the other privately.", hint: "Remove the cause." },
    { kind: "concept", title: "Stay calm", body: "The crowd does not know your plan. If you stay calm, a fix can sound like a decision. Panic is what makes a small error obvious.", keyFact: "Calm makes mistakes small." },
    { kind: "quiz", q: "Your USB suddenly stops reading in the middle of a track. What is your best move?", options: ["Keep the other deck playing and switch to your spare USB", "Panic", "Leave the booth", "Mute everything"], answer: 0, explain: "A spare drive and a second deck are exactly what you prepared for.", hint: "That is why you brought two." },
    { kind: "quiz", q: "After a gig you realise you made a poor transition. What helps most?", options: ["Note it and practise that transition", "Stop DJing", "Blame the gear", "Ignore it"], answer: 0, explain: "Every mistake is a pointer to something to practise. Writing it down turns it into improvement.", hint: "Use it." },
    { kind: "quiz", q: "From an earlier lesson: what does a kick heard twice, slightly apart, mean?", options: ["The beats are not aligned", "The key is wrong", "The speakers are broken", "The tracks are perfect"], answer: 0, explain: "A flam between two kicks means a phase offset to nudge out." },
    { kind: "summary", learned: ["Take the clashing track out and fix it in your headphones", "Calm recovery often goes unnoticed", "Use every mistake as a practice target"] },
  ],

  "effects-deep-dj": [
    { kind: "hook", emoji: "", headline: "Effects can be part of the music", subtext: "Used well, they shape a transition instead of decorating it." },
    { kind: "concept", title: "Echo length changes the feel", body: "A short echo, such as half a beat, sounds tight and rhythmic. A long echo, such as a bar, sounds big and spacious. The tail decays on its own, so you can leave it ringing over a quiet moment.", keyFact: "Short echo is tight. Long echo is spacious." },
    { kind: "interact", sim: "mixer", prompt: "Throw an echo on the last beat. Let it ring." },
    { kind: "concept", title: "Reverb and phaser", body: "Reverb adds space. Turned up it swells and blurs the sound, which hides a join. A phaser sweeps a moving, swirling colour through the track, which adds motion to a steady section.", keyFact: "Reverb blurs. Phaser moves." },
    { kind: "quiz", q: "You want a tight, rhythmic echo on a busy hi-hat part. Which size fits best?", options: ["A short echo, a fraction of a beat", "A very long echo", "No echo", "A reverb wash"], answer: 0, explain: "A short echo stays in time and adds groove. A long one smears a busy part.", hint: "Tight or spacious?" },
    { kind: "quiz", q: "You throw a long echo on a dense drop and it turns to mush. What is the fix?", options: ["Use effects on sparse sections and keep the wet amount lower", "Make it louder", "Add more echo", "Stop using effects forever"], answer: 0, explain: "Effects need space to be heard. Dense music hides them or turns muddy.", hint: "Where is the space?" },
    { kind: "match", prompt: "Match the effect to its use", pairs: [{ left: "Short echo", right: "Tight rhythmic repeats" }, { left: "Long echo", right: "Big spacious tail" }, { left: "Reverb wash", right: "Blurs a join" }, { left: "Phaser", right: "Adds sweeping motion" }] },
    { kind: "concept", title: "Practise in private", body: "Learn each effect on its own at home. Know what each knob does, how much is too much and how long a tail lasts at your tempo.", keyFact: "Learn it at home, not on the night." },
    { kind: "quiz", q: "From an earlier lesson: what is the golden rule of effects?", options: ["Use them with restraint and a reason", "Use as many as possible", "Always use reverb", "Only use them at the drop"], answer: 0, explain: "Effects work when they are unusual and purposeful." },
    { kind: "summary", learned: ["Echo length sets the feel", "Reverb blurs, phaser adds motion", "Use effects in sparse sections"] },
  ],

  "loop-performance-dj": [
    { kind: "hook", emoji: "", headline: "Loops let you play with time", subtext: "Tighten a loop and the tension climbs." },
    { kind: "concept", title: "Loops that build", body: "Start a loop of four bars and halve it: two bars, one bar, half a bar. Each halving repeats more often, which increases urgency. Release on a downbeat and the track continues as if nothing had happened, with the tension released.", keyFact: "Halving a loop raises tension." },
    { kind: "interact", sim: "loop-roll", prompt: "Loop four bars. Halve it. Release." },
    { kind: "quiz", q: "You loop four bars, halve to two, then one, then release on the downbeat. What does the crowd feel?", options: ["A build that releases on the downbeat", "Nothing", "A key change", "A tempo drop"], answer: 0, explain: "The faster repeats raise anticipation and the release feels like a drop.", hint: "Think about the pace of repeats." },
    { kind: "concept", title: "Loops and transitions", body: "Looping a breakdown or outro holds the music steady while you set up the next track. Looping a short peak section can extend a high moment, but use it sparingly or it becomes repetitive.", keyFact: "Loop a calm section to buy time." },
    { kind: "quiz", q: "You loop a peak section for two minutes. The crowd starts to drift. What is the problem?", options: ["Too much repetition, so release the loop or change something", "The loop is too quiet", "The key is wrong", "The tempo is wrong"], answer: 0, explain: "A loop is a tool to build or buy time. Held too long, the lack of change loses people.", hint: "Variety." },
    { kind: "match", prompt: "Match the loop use to its purpose", pairs: [{ left: "Loop the breakdown", right: "Buy time for the next track" }, { left: "Halve the loop", right: "Raise tension" }, { left: "Loop roll on a snare", right: "Rhythmic stutter" }, { left: "Release on the downbeat", right: "Feels like the drop" }] },
    { kind: "concept", title: "Release on the beat", body: "Release a loop exactly on a downbeat of a phrase so the track rejoins in time. A loose release sounds like an error.", keyFact: "Release on a downbeat." },
    { kind: "quiz", q: "From an earlier lesson: what do loops depend on?", options: ["A correct beat grid", "A high BPM", "A certain key", "A big USB"], answer: 0, explain: "Loops snap to the grid, so a wrong grid makes them sound off." },
    { kind: "summary", learned: ["Halving a loop builds tension", "Loop calm sections to buy time", "Release on a downbeat"] },
  ],

  "harmonic-key-shift-dj": [
    { kind: "hook", emoji: "", headline: "Change the key without changing the speed", subtext: "Key lock is the tool behind modern harmonic mixing." },
    { kind: "concept", title: "What key lock does", body: "Normally speeding a track up also raises its pitch. Key lock, called Master Tempo on Pioneer CDJs and MT in rekordbox, keeps the pitch steady while the tempo changes. That is why you can beatmatch without everything sounding higher or lower.", keyFact: "Key lock: tempo changes, pitch stays." },
    { kind: "interact", sim: "ear-training", preset: { mode: "high-low" }, prompt: "Listen. Hear higher and lower pitch." },
    { kind: "quiz", q: "You speed a track up by 6 percent with key lock off. What happens to the pitch?", options: ["It rises with the tempo", "It stays the same", "It falls", "It disappears"], answer: 0, explain: "Without key lock, tempo and pitch move together, like a record played faster.", hint: "Think of a record." },
    { kind: "concept", title: "Limits", body: "Key lock works by processing the audio, and the further you push the tempo the more you may hear the processing. Changes of a few percent are usually fine. Bigger moves can sound strained, especially on vocals and sparse sounds.", keyFact: "Small changes sound clean. Big ones show the processing." },
    { kind: "concept", title: "Shifting the key", body: "Some players and software can shift the key by semitones independently of tempo. A shift of a semitone or two can bring a track into a compatible key, but big shifts tend to sound artificial, so use your ear.", keyFact: "Small shifts first. Trust your ear." },
    { kind: "quiz", q: "A track is one semitone away from the key you need. What is the sensible move?", options: ["Try a small key shift and listen to how it sounds", "Shift it five semitones", "Ignore the key", "Slow the tempo by half"], answer: 0, explain: "Small shifts are less noticeable. Check by ear because vocals and acoustic sounds reveal processing sooner.", hint: "Small and checked." },
    { kind: "quiz", q: "With key lock on, you raise the tempo by a few percent. What happens to the key?", options: ["It stays the same", "It rises a lot", "It falls", "It becomes minor"], answer: 0, explain: "That is exactly what key lock is for: the tempo moves and the pitch stays." },
    { kind: "quiz", q: "From an earlier lesson: what does the Camelot wheel help you choose?", options: ["Keys that blend well", "Cue points", "Effect length", "Loop sizes"], answer: 0, explain: "It shows which keys sit close together." },
    { kind: "summary", learned: ["Key lock keeps pitch steady as tempo changes", "Big tempo moves can sound strained", "Small key shifts are safer, trust your ear"] },
  ],

  "stem-djing": [
    { kind: "hook", emoji: "", headline: "Take a track apart and mix the pieces", subtext: "Stems let you keep the drums and swap the rest." },
    { kind: "concept", title: "What stems are", body: "rekordbox can separate a track into parts so you can control them individually. In rekordbox 7 you can choose three stems (vocal, instruments and drums) or four (vocal, instruments, bass and drums). Check which mode your version uses.", keyFact: "3 or 4 stems: vocal, instruments, drums, and bass in four-stem mode." },
    { kind: "interact", sim: "mixer", prompt: "Hold the drums. Swap the rest." },
    { kind: "concept", title: "Stems in a transition", body: "Keep the drums from both tracks running so the rhythm never changes, and swap the bass and instruments between them. You can also mute the vocal of one track so it does not fight the other.", keyFact: "Keep the rhythm. Swap the rest." },
    { kind: "quiz", q: "Two tracks have strong vocals that clash during your blend. With stems, what is a clean fix?", options: ["Mute the vocal stem of one track", "Raise both vocals", "Speed up one", "Cut the highs on the master"], answer: 0, explain: "Muting one vocal gives the other room without touching the rest of the track.", hint: "Take out the part that clashes." },
    { kind: "quiz", q: "The separated vocal has a faint hint of the drums in it. Why?", options: ["Separation is not perfect, so some leakage can remain", "The file is damaged", "The key is wrong", "The BPM is wrong"], answer: 0, explain: "Separation is an estimate. Complex mixes can leave traces of other parts in a stem.", hint: "It is processing, not magic." },
    { kind: "match", prompt: "Match the stem to what it carries", pairs: [{ left: "Vocal", right: "Singing and spoken parts" }, { left: "Instruments", right: "Melodic and harmonic parts" }, { left: "Drums", right: "The rhythmic backbone" }, { left: "Bass (four-stem mode)", right: "The low end" }] },
    { kind: "concept", title: "Check your setup", body: "Stems are a rekordbox feature with their own settings, and some controls need a particular plan or hardware. Check the rekordbox support page for what your setup supports before you rely on them in a gig.", keyFact: "Check what your plan and hardware support." },
    { kind: "quiz", q: "From an earlier lesson: why swap the bass during a blend?", options: ["So only one bass line plays at a time", "To raise the tempo", "To change the key", "To lower the master"], answer: 0, explain: "Two bass lines at once crowd the low end." },
    { kind: "summary", learned: ["rekordbox stems are 3 or 4 parts, including vocal and drums", "Keep drums, swap bass and instruments, or mute a clashing vocal", "Separation is imperfect and depends on your setup"] },
  ],

  "recording-your-set-dj": [
    { kind: "hook", emoji: "", headline: "You cannot judge a mix while you are playing it", subtext: "Record it. Listen back. Fix one thing." },
    { kind: "concept", title: "Ways to record", body: "You can record the output of your DJ software, or record the mixer's output with a separate recorder. A recorder on the mixer's record output captures what the mixer actually sends, whatever the source. Either way, check that it is recording before you start.", keyFact: "Record the mix, and check it is recording." },
    { kind: "interact", sim: "mixer", prompt: "Watch the meter. Keep peaks out of the red." },
    { kind: "concept", title: "Recording level", body: "Leave headroom so the recording does not clip. Peaks around minus 6 dBFS are a common target because they leave room for editing later. Never let it hit the maximum, because digital clipping cannot be repaired.", keyFact: "Peaks near minus 6 dBFS leave headroom." },
    { kind: "quiz", q: "Your recording is full of crackling distortion that was not in the room. What is the likely cause?", options: ["The recording level was too hot and clipped", "The tracks were in the wrong key", "The tempo was off", "The headphones were muted"], answer: 0, explain: "Clipping at the recorder is permanent. Setting a safer level avoids it.", hint: "Too loud going in." },
    { kind: "concept", title: "Listen like a coach", body: "When you listen back, pick one thing to improve and one thing that worked. Write both down. A specific note such as \"bass swap came late\" gives you something to practise.", keyFact: "One fix, one success, written down." },
    { kind: "quiz", q: "You listen to a recording and think \"it was fine\". How can you make the listen useful?", options: ["Choose one specific transition and note what to improve", "Listen once and move on", "Delete it", "Play it louder"], answer: 0, explain: "Specific notes lead to specific practice. General impressions rarely change what you do next.", hint: "Be specific." },
    { kind: "quiz", q: "From an earlier lesson: why record practice mixes?", options: ["You can hear mistakes you missed while playing", "To save space", "To change the key", "To raise the tempo"], answer: 0, explain: "In the moment you are busy. Listening back lets you hear what happened." },
    { kind: "quiz", q: "A set recording can also be used for what?", options: ["A promo mix to show promoters your sound", "Nothing", "A key shift", "A cue point"], answer: 0, explain: "A good recorded set doubles as an audio CV for bookings." },
    { kind: "summary", learned: ["Record the mix and check it is recording", "Keep peaks around minus 6 dBFS", "Listen back for one fix and one success"] },
  ],

  "dvs-basics": [
    { kind: "hook", emoji: "", headline: "Real vinyl feel, digital library", subtext: "A DVS lets a record control a computer." },
    { kind: "concept", title: "How it works", body: "A DVS uses special control vinyl or CDs with an encoded signal. A turntable or CD player plays it, and the software reads the signal to work out the position and speed of the record. That movement then controls a digital file, so a scratch on the vinyl scratches the file.", keyFact: "The record carries a signal. The software reads it." },
    { kind: "interact", sim: "routing-puzzle", prompt: "Connect turntable, interface and laptop." },
    { kind: "concept", title: "What you need", body: "You need control records, turntables or CD players, a supported audio interface or mixer, and DVS software such as Serato DJ Pro or Traktor Scratch. Each software supports certain hardware, so check the compatibility list before you buy.", keyFact: "Control records, players, supported interface, software." },
    { kind: "quiz", q: "You buy DVS software but your audio interface is not on its supported list. What is the risk?", options: ["It may not work or be unsupported", "None", "The key changes", "The tempo doubles"], answer: 0, explain: "DVS software works with specific hardware. Check the list before buying.", hint: "Compatibility." },
    { kind: "quiz", q: "Why would a turntablist choose DVS over carrying crates of vinyl?", options: ["They keep the feel of vinyl with a large digital library", "It is cheaper always", "It plays itself", "It removes the need for a mixer"], answer: 0, explain: "DVS keeps hands-on control while the library lives on the laptop.", hint: "Feel and library." },
    { kind: "match", prompt: "Match the part to its job", pairs: [{ left: "Control vinyl", right: "Carries the encoded signal" }, { left: "Audio interface", right: "Passes signal between deck and laptop" }, { left: "Software", right: "Reads position and plays the file" }, { left: "Mixer", right: "Blends the channels" }] },
    { kind: "concept", title: "Risks", body: "A DVS adds a laptop and cables between the record and the sound. Know how to switch to another source if something fails, and carry spares.", keyFact: "More parts, more to check." },
    { kind: "quiz", q: "From an earlier lesson: what input does a turntable connect to on a mixer?", options: ["PHONO", "LINE for everything", "Booth", "Headphone"], answer: 0, explain: "A turntable's weak signal needs the phono preamp. With a DVS you often connect through the interface instead, so check your setup." },
    { kind: "summary", learned: ["A DVS reads an encoded signal from a record to control a file", "You need compatible hardware and software", "More parts means more to check before a gig"] },
  ],

  "dj-business": [
    { kind: "hook", emoji: "", headline: "Talent gets you noticed. Reliability gets you rebooked.", subtext: "The business side of DJing is mostly professionalism." },
    { kind: "concept", title: "Your promo mix", body: "A promo mix is a recording of your sound at its best, usually an hour or so, that promoters can listen to quickly. Put it where it is easy to find, with a clear name, a photo and a short bio. One strong mix beats several average ones.", keyFact: "One strong mix, easy to find." },
    { kind: "interact", sim: "none", prompt: "List what a promoter needs from you." },
    { kind: "concept", title: "Rates and rider", body: "Find out what DJs at your level are paid in your area and do not undercut wildly, because it hurts you and others. A rider lists what you need in writing, such as equipment, travel or hospitality, so there are no surprises on the night.", keyFact: "Know the going rate. Put needs in writing." },
    { kind: "quiz", q: "A promoter offers a fee far below what other DJs at your level earn locally. What is a sensible approach?", options: ["Check local rates and negotiate, or decline if it does not work", "Accept at once", "Ignore the message", "Charge double"], answer: 0, explain: "Knowing local rates lets you negotiate fairly. Undercutting hurts your income and the scene.", hint: "Know the market." },
    { kind: "quiz", q: "Which habit most reliably gets you rebooked?", options: ["Arriving on time, prepared, and doing what you promised", "Playing very loud", "Being late but brilliant", "Never replying to messages"], answer: 0, explain: "Promoters remember who made their night easy. Reliability matters as much as talent.", hint: "Think like a promoter." },
    { kind: "match", prompt: "Match the item to its purpose", pairs: [{ left: "Promo mix", right: "Shows your sound" }, { left: "Rider", right: "Lists your requirements" }, { left: "Bio and photo", right: "Presents who you are" }, { left: "Rate", right: "What you charge" }] },
    { kind: "concept", title: "Reply and follow up", body: "Answer messages promptly, confirm details in writing and thank the promoter afterwards. Small courtesies make you easy to work with.", keyFact: "Easy to work with gets booked again." },
    { kind: "quiz", q: "From an earlier lesson: why research a gig before you play it?", options: ["So the set fits the crowd and the slot", "To raise the tempo", "To change the key", "To avoid soundcheck"], answer: 0, explain: "Knowing the room and slot lets you prepare tracks that fit." },
    { kind: "summary", learned: ["A strong promo mix is your audio CV", "Know local rates and put needs in a rider", "Reliability brings repeat bookings"] },
  ],

  "dj-advanced-complete": [
    { kind: "hook", emoji: "", headline: "Technique is the floor. Taste is the ceiling.", subtext: "What people remember is your point of view." },
    { kind: "concept", title: "From competent to distinctive", body: "Most people can learn to beatmatch and blend. What sets a DJ apart is a point of view: the tracks they find, the order they choose, and the feeling they build over a night. That comes from listening widely and making decisions.", keyFact: "Taste and point of view set you apart." },
    { kind: "interact", sim: "none", prompt: "Write the next step for your sound." },
    { kind: "concept", title: "Ways to grow", body: "Keep digging for music others do not have. Make your own edits or tracks if you can, since nobody else will have them. Build relationships with other DJs, promoters and listeners. Let your sound change over years rather than weeks.", keyFact: "Dig, make, connect, give it time." },
    { kind: "quiz", q: "You can mix cleanly, but your sets sound like everyone else's. What is the most useful next step?", options: ["Dig for music others do not have and make clear choices", "Buy more gear", "Play faster", "Copy a famous set"], answer: 0, explain: "Distinctive taste comes from what you find and how you choose. Technique alone does not set you apart.", hint: "Taste, not tools." },
    { kind: "quiz", q: "Why might making your own edits or tracks help a DJ?", options: ["You can play music nobody else has", "They are always better", "It removes the need for mixing", "It raises the tempo"], answer: 0, explain: "Your own music gives you something unique and a sound others recognise.", hint: "Exclusive." },
    { kind: "sequence", prompt: "Put a growth cycle in order", items: ["Listen widely", "Choose what moves you", "Play it for a room", "Record and review", "Adjust and repeat"], explain: "Each loop of listening, choosing, playing and reviewing teaches you more than any single gig." },
    { kind: "concept", title: "Stay curious", body: "The best DJs keep listening, keep practising and keep taking small risks. Revisit the basics now and then, because they underlie everything else.", keyFact: "Stay curious. Keep the basics sharp." },
    { kind: "quiz", q: "From an earlier lesson: what is the first thing to check if a blend sounds crowded?", options: ["Whether bass and vocals from both tracks are clashing", "The gig fee", "The USB brand", "The lighting"], answer: 0, explain: "Clashing bass and mids are the usual cause, and EQ is the fix." },
    { kind: "summary", learned: ["Taste and point of view set a DJ apart", "Dig, make, connect and give your sound time", "Keep the basics sharp as you grow"] },
  ],
};
